questionvariables.text:
/* 1. Calcul caché pour générer les réponses */
z_calc: (3+2*%i)/(1-%i);

/* 2. Extraction automatique des parties réelle et imaginaire par Maxima */
ta_re: realpart(z_calc);
ta_im: imagpart(z_calc);

/* 3. Affichage forcé de z sans simplification */
texput(z, "\\dfrac{3 + 2i}{1 - i}");
